    keyboardTouchpadHealth: text("keyboardTouchpadHealth"),
    bodyHingeHealth: text("bodyHingeHealth"),
    batteryHealthPercent: text("batteryHealthPercent", 3)
      .replace(/\D/g, "")
      .slice(0, 3),
