      .replace(/\D/g, "")
      .slice(0, 3),
    returnPolicy: text("returnPolicy"),
    notes: text("notes", 1000),
  };
}

function validateOfferProductSpecs(specs: OfferProductSpecs) {
  const required: Array<keyof OfferProductSpecs> = [
    "brand",
    "exactModel",
    "cpu",
    "ram",
    "storage",
    "manufactureYear",
    "productCondition",
    "warrantyStatus",
    "partsHealth",
    "cpuHealth",
    "motherboardHealth",
    "displayHealth",
    "storageHealth",
    "ramHealth",
    "keyboardTouchpadHealth",
    "bodyHingeHealth",
    "appearanceGrade",
    "repairHistory",
    "usageLevel",
    "accessoriesStatus",
    "chargerStatus",
    "returnPolicy",
  ];
  return required
    .filter((key) => !specs[key] || specs[key] === "unknown")
    .map((key) => offerSpecLabels[key]);
}

