}

function DocumentInput({
  label,
  help,
  file,
  files = [],
  multiple = false,
  onChange,
}: {
  label: string;
  help: string;
  file?: File | null;
  files?: File[];
  multiple?: boolean;
  onChange: (files: File[]) => void;
}) {
  const selectedFiles = multiple ? files : file ? [file] : [];

  return (
    <div className="rounded-xl border border-amber-100 bg-white p-4">
      <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
        <div>
          <p className="text-sm font-bold text-gray-800">{label}</p>
          <p className="mt-1 text-xs text-gray-500">{help}</p>
        </div>
        <label className="cursor-pointer rounded-lg bg-[#003b5c] px-4 py-2.5 text-center text-xs font-bold text-white transition hover:bg-[#002d46]">
          انتخاب {multiple ? "تصاویر" : "تصویر"}
          <input
            type="file"
            accept="image/jpeg,image/png,image/webp"
            multiple={multiple}
            className="hidden"
            onChange={(event) => {
              const selected = Array.from(event.target.files || []);
              const invalid = selected.find(
                (item) =>
                  !["image/jpeg", "image/png", "image/webp"].includes(
                    item.type,
                  ) || item.size > 5 * 1024 * 1024,
              );
              if (invalid) {
                alert(
                  "فقط تصاویر JPG، PNG یا WEBP با حداکثر حجم ۵ مگابایت مجاز هستند.",
                );
                event.target.value = "";
                return;
              }
              onChange(selected);
            }}
          />
        </label>
      </div>
      {selectedFiles.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-2 border-t border-gray-100 pt-3">
          {selectedFiles.map((item, index) => (
            <span
              key={`${item.name}-${index}`}
              className="rounded-lg bg-green-50 px-3 py-2 text-xs font-bold text-green-700"
            >
              ✓ {item.name} —{" "}
              {(item.size / 1024).toLocaleString("fa-IR", {
                maximumFractionDigits: 0,
              })}{" "}
              کیلوبایت
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

