                  </option>
                  <option value="unknown">نامشخص</option>
                </select>
              </label>

              <label className="block text-sm font-bold text-gray-700">
                جعبه اصلی
                <select
                  value={formData.valuationFactors.originalPackaging}
                  onChange={(e) =>
                    updateValuationFactor("originalPackaging", e.target.value)
                  }
                  className="mt-2 w-full rounded-lg border border-gray-300 px-4 py-3 font-normal outline-none focus:ring-2 focus:ring-green-500"
                >
                  <option value="yes">دارد</option>
                  <option value="no">ندارد</option>
                  <option value="unknown">نامشخص</option>
                </select>
              </label>

              <label className="block text-sm font-bold text-gray-700">
                فاکتور خرید / اصالت
                <select
                  value={formData.valuationFactors.purchaseInvoiceAvailable}
                  onChange={(e) =>
                    updateValuationFactor(
                      "purchaseInvoiceAvailable",
                      e.target.value,
                    )
                  }
                  className="mt-2 w-full rounded-lg border border-gray-300 px-4 py-3 font-normal outline-none focus:ring-2 focus:ring-green-500"
                >
                  <option value="yes">فاکتور یا مدرک اصالت دارد</option>
                  <option value="no">ندارد</option>
                  <option value="unknown">نامشخص</option>
                </select>
              </label>

              <label className="block text-sm font-bold text-gray-700">
                وضعیت موجودی در بازار
                <select
                  value={formData.valuationFactors.marketAvailability}
                  onChange={(e) =>
                    updateValuationFactor("marketAvailability", e.target.value)
                  }
                  className="mt-2 w-full rounded-lg border border-gray-300 px-4 py-3 font-normal outline-none focus:ring-2 focus:ring-green-500"
                >
                  <option value="available">موجود و رایج</option>
                  <option value="rare">کمیاب</option>
                  <option value="discontinued">توقف تولید / قدیمی</option>
                  <option value="unknown">نامشخص</option>
                </select>
              </label>
            </div>

            <label className="mt-4 block text-sm font-bold text-gray-700">
              توضیحات تکمیلی ارزش‌گذاری
              <textarea
                value={formData.valuationFactors.valuationNotes}
                onChange={(e) =>
                  updateValuationFactor("valuationNotes", e.target.value)
                }
                placeholder="مثلاً: خط روی بدنه، تعویض باتری، شارژر غیر اصل، تست سلامت، شماره سریال، وضعیت پلمب و ..."
                className="mt-2 min-h-24 w-full rounded-lg border border-gray-300 px-4 py-3 font-normal outline-none focus:ring-2 focus:ring-green-500"
              />
            </label>
          </div>

          {/* Product Photos */}
          <div className="bg-white rounded-xl p-6 shadow-sm border border-gray-100">
            <h2 className="text-xl font-bold mb-4">عکس محصول (اختیاری)</h2>
            <p className="text-sm text-gray-500 mb-4">
              عکس‌های محصول موردنیاز را بارگذاری کنید؛ این عکس‌ها بعد از ثبت در
              صفحه اصلی، صفحه درخواست و لیست درخواست‌ها کنار نام محصول نمایش
              داده می‌شوند.
            </p>

            <div className="border-2 border-dashed border-green-300 bg-green-50/50 hover:bg-green-50 rounded-lg p-8 text-center transition relative">
              <input
                type="file"
                multiple
                accept="image/jpeg,image/png,image/webp"
                onChange={handleFileChange}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                title="برای انتخاب فایل کلیک کنید"
              />
              <svg
                className="w-12 h-12 text-green-500 mx-auto mb-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m0-3v12"
                />
              </svg>
              <p className="text-green-800 font-bold mb-2">
                برای آپلود کلیک کنید یا فایل‌ها را اینجا بکشید و رها کنید
              </p>
              <button
                type="button"
                className="mt-2 bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 transition font-bold pointer-events-none relative z-10"
              >
                انتخاب عکس‌های محصول
              </button>
              <p className="text-gray-400 text-sm mt-4">
                حداکثر ۸ عکس | حجم هر عکس حداکثر ۵ مگابایت | فرمت‌ها: JPG, PNG,
                WEBP
              </p>
            </div>

            {/* Preview Section */}
            {uploadedFiles.length > 0 && (
              <div className="mt-6 border-t border-gray-100 pt-6">
                <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                  <svg
                    className="w-5 h-5 text-green-600"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                    />
                  </svg>
                  عکس‌های انتخاب‌شده ({uploadedFiles.length})
                </h3>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                  {previews.map((src, index) => (
                    <div
                      key={index}
                      className="relative group rounded-xl border border-gray-200 bg-gray-50 overflow-hidden aspect-square flex flex-col items-center justify-center p-2"
                    >
                      {uploadedFiles[index].type.startsWith("image/") ? (
                        <img
                          src={src}
                          alt="preview"
                          className="w-full h-full object-cover rounded-lg"
                        />
                      ) : (
                        <div className="flex flex-col items-center gap-2">
                          <svg
                            className="w-10 h-10 text-gray-400"
                            fill="currentColor"
                            viewBox="0 0 20 20"
                          >
                            <path
                              fillRule="evenodd"
                              d="M4 4a2 2 0 012-2h4.586A2 2 0 0112 2.586L15.414 6A2 2 0 0116 7.414V16a2 2 0 01-2 2H6a2 2 0 01-2-2V4z"
                              clipRule="evenodd"
                            />
                          </svg>
                          <span className="text-xs text-gray-500 font-mono truncate w-full text-center px-2">
                            {uploadedFiles[index].name}
                          </span>
                        </div>
                      )}

                      {/* Delete Overlay */}
                      <button
                        type="button"
                        onClick={(e) => {
                          e.preventDefault();
                          removeFile(index);
                        }}
                        className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                        title="حذف فایل"
                      >
                        <svg
                          className="w-8 h-8 text-white hover:text-red-500 transition"
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                          />
                        </svg>
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Security Info */}
          <div className="bg-green-50 border border-green-200 rounded-xl p-6">
            <h3 className="font-bold text-green-800 mb-3 flex items-center gap-2">
              <svg
                className="w-5 h-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"
                />
              </svg>
              پرداخت امن با سیستم امانت‌داری
            </h3>
            <p className="text-green-700 text-sm">
              پس از انتخاب پیشنهاد فروشنده، مبلغ پرداختی شما نزد پلتفرم امانت
              می‌ماند. پس از تحویل کالا و تایید نهایی شما، وجه (با کسر کمیسیون
              پلتفرم) به فروشنده واریز می‌شود.
            </p>
          </div>

          {/* Submit */}
          <div className="bg-white rounded-xl p-6 shadow-sm border border-gray-100">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
              <p className="text-gray-600 text-sm">
                با ثبت درخواست، شما{" "}
                <Link href="/rules" className="text-green-600 hover:underline">
                  قوانین و مقررات
                </Link>{" "}
                OptiBid را می‌پذیرید
              </p>
              <button
                type="submit"
                disabled={isSubmitting}
                className={`text-white px-8 py-3 rounded-lg font-bold transition w-full sm:w-auto ${
                  isSubmitting
                    ? "bg-gray-400 cursor-not-allowed"
                    : "bg-green-600 hover:bg-green-700"
                }`}
              >
                {isSubmitting
                  ? "در حال ذخیره در دیتابیس..."
                  : "ثبت درخواست خرید در پایگاه داده"}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

files.src/app/requests/RequestsListClient.tsx:
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { ProductImageStrip, ProductThumb } from "@/components/ProductImages";
import UserAvatar from "@/components/UserAvatar";
import type { ProductImageAttachment } from "@/lib/product-image-shared";

interface SellerOfferSummary {
  id: number;
  sellerId: number;
  sellerName: string;
  amount: string;
  deliveryDays: number;
  status: "pending" | "accepted" | "rejected";
  message: string;
  productSpecs?: any;
  productImages?: ProductImageAttachment[];
  seller?: { id: number; fullName: string; avatarName?: string };
}

interface RequestItem {
  id: string | number;
  title: string;
  description: string;
  budget: string;
  category: string;
  timeAgo: string;
  offers: number;
  buyer: string;
  buyerRating: number;
  buyerUser?: { id: number; fullName: string; avatarName?: string };
  latestSeller?: { id: number; fullName: string; avatarName?: string };
  quantity: number;
  deadline: string;
  sellerOffers: SellerOfferSummary[];
  productImages?: ProductImageAttachment[];
}

export default function RequestsListClient({
  initialRequests,
  allCategories,
}: {
  initialRequests: RequestItem[];
  allCategories: string[];
}) {
  const [selectedCategory, setSelectedCategory] = useState("همه دسته‌بندی‌ها");
  const [searchQuery, setSearchQuery] = useState("");
  const [specsRequest, setSpecsRequest] = useState<RequestItem | null>(null);
  const [userRole, setUserRole] = useState<string | null>(null);

  useEffect(() => {
    setUserRole(localStorage.getItem("userRole"));
  }, []);

  // فیلتر کردن زنده (Instant Filter)
  const filteredRequests = initialRequests.filter((req) => {
    // 1. فیلتر دسته‌بندی
    const matchCategory =
      selectedCategory === "همه دسته‌بندی‌ها" ||
      req.category === selectedCategory;

    // 2. فیلتر جستجوی متنی
    const matchSearch =
      req.title.includes(searchQuery) || req.description.includes(searchQuery);

    return matchCategory && matchSearch;
  });

  return (
    <div dir="rtl" className="min-h-screen bg-gray-50">
      {specsRequest && (
        <OfferSpecsModal
          request={specsRequest}
          onClose={() => setSpecsRequest(null)}
        />
      )}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">
                درخواست‌های خرید
              </h1>
              <p className="text-gray-600">
                درخواست‌های خرید ثبت شده توسط خریداران را مشاهده کنید و پیشنهاد
                دهید
              </p>
            </div>
            <Link
              href="/request-purchase"
              className="bg-green-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-green-700 transition flex items-center gap-2"
            >
              <svg
                className="w-5 h-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 4v16m8-8H4"
                />
              </svg>
              ثبت درخواست خرید
            </Link>
          </div>
        </div>

        <div className="flex flex-col md:flex-row gap-6">
          {/* Sidebar Filters */}
          <aside className="md:w-64 flex-shrink-0">
            <div className="bg-white rounded-xl p-6 shadow-sm border border-gray-100 sticky top-24">
              <h3 className="font-bold text-lg mb-4">فیلترها</h3>

              {/* Category Filter */}
              <div className="mb-6">
                <h4 className="font-medium text-gray-700 mb-3">دسته‌بندی</h4>
                <select
                  value={selectedCategory}
                  onChange={(e) => setSelectedCategory(e.target.value)}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent outline-none transition bg-gray-50"
                >
                  {allCategories.map((cat, i) => (
                    <option key={i} value={cat}>
                      {cat}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-green-600 mt-2">
                  ✨ فیلتر بلافاصله اعمال می‌شود
                </p>
              </div>

              {/* Budget Filter */}
              <div className="mb-6">
                <h4 className="font-medium text-gray-700 mb-3">محدوده بودجه</h4>
                <div className="space-y-2">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      className="w-4 h-4 text-green-600 rounded"
                    />
                    <span className="text-gray-600">زیر ۱۰ میلیون تومان</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      className="w-4 h-4 text-green-600 rounded"
                    />
                    <span className="text-gray-600">۱۰ تا ۵۰ میلیون تومان</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      className="w-4 h-4 text-green-600 rounded"
                    />
                    <span className="text-gray-600">
                      ۵۰ تا ۱۰۰ میلیون تومان
                    </span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      className="w-4 h-4 text-green-600 rounded"
                    />
                    <span className="text-gray-600">
                      بالای ۱۰۰ میلیون تومان
                    </span>
                  </label>
                </div>
              </div>

              {/* Time Filter */}
              <div className="mb-6">
                <h4 className="font-medium text-gray-700 mb-3">زمان ثبت</h4>
                <div className="space-y-2">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name="time"
                      className="w-4 h-4 text-green-600"
                      defaultChecked
                    />
                    <span className="text-gray-600">همه زمان‌ها</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name="time"
                      className="w-4 h-4 text-green-600"
                    />
                    <span className="text-gray-600">۲۴ ساعت گذشته</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name="time"
                      className="w-4 h-4 text-green-600"
                    />
                    <span className="text-gray-600">هفته گذشته</span>
                  </label>
                </div>
              </div>
            </div>
          </aside>

          {/* Requests List */}
          <div className="flex-1">
            {/* Search Bar */}
            <div className="bg-white rounded-xl p-4 shadow-sm border border-gray-100 mb-6">
              <div className="flex gap-4">
                <input
                  type="text"
                  placeholder="جستجو در متن یا عنوان درخواست‌ها..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="flex-1 border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-green-500 focus:border-transparent outline-none"
                />
              </div>
            </div>

            {/* Requests */}
            <div className="space-y-4">
              {filteredRequests.length === 0 ? (
                <div className="bg-white rounded-xl p-10 text-center border border-gray-200">
                  <p className="text-gray-500 font-bold mb-2">
                    هیچ درخواستی با این فیلترها یافت نشد.
                  </p>
                  <button
                    onClick={() => {
                      setSelectedCategory("همه دسته‌بندی‌ها");
                      setSearchQuery("");
                    }}
                    className="text-green-600 hover:underline text-sm"
                  >
                    حذف فیلترها و مشاهده همه
                  </button>
                </div>
              ) : (
                filteredRequests.map((request) => (
                  <div
                    key={request.id}
                    className="bg-white rounded-xl p-6 shadow-sm border border-gray-100 card-hover block"
                  >
                    <div className="flex flex-wrap items-start justify-between gap-4 mb-4">
                      <div className="flex items-center gap-2">
                        <span className="bg-blue-50 text-[#00a8e8] border border-[#00a8e8]/30 px-3 py-1 rounded-full text-sm font-bold">
                          {request.category}
                        </span>
                        <span className="bg-gray-100 text-gray-600 px-3 py-1 rounded-full text-sm font-bold">
                          تعداد: {request.quantity}
                        </span>
                      </div>
                      <span className="text-gray-400 text-sm font-bold">
                        {request.timeAgo}
                      </span>
                    </div>

                    <div className="mb-3 flex items-center gap-3">
                      <ProductThumb
                        images={request.productImages}
                        title={String(request.title)}
                        className="h-20 w-20"
                      />
                      <div className="min-w-0">
                        <h3 className="font-bold text-xl text-gray-800">
                          {request.title}
                        </h3>
                        {request.productImages?.length ? (
                          <p className="mt-1 text-xs text-gray-500">
                            {request.productImages.length.toLocaleString(
                              "fa-IR",
                            )}{" "}
                            عکس محصول خریدار
                          </p>
                        ) : null}
                      </div>
                    </div>
                    <p className="text-gray-600 mb-4 line-clamp-2">
                      {request.description}
                    </p>

                    <div className="flex items-center gap-4 mb-4 text-sm text-gray-500">
                      <span className="flex items-center gap-1">
                        <svg
                          className="w-4 h-4"
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                          />
                        </svg>
                        مهلت: {request.deadline}
                      </span>
                    </div>

                    <div className="flex flex-wrap items-center justify-between gap-4 pt-4 border-t border-gray-100">
                      <div className="flex items-center gap-4">
                        <span className="font-bold text-xl md:text-2xl text-green-600">
                          {request.budget}
                        </span>
                        <div className="flex flex-wrap items-center gap-3 text-sm text-gray-500">
                          <div className="flex items-center gap-2 rounded-xl bg-white px-2 py-1">
                            <UserAvatar
                              user={request.buyerUser}
                              label={request.buyer}
                              className="h-9 w-9"
                              rounded="rounded-full"
                            />
                            <span>
                              خریدار:{" "}
                              <b className="text-gray-800">{request.buyer}</b>
                            </span>
                            <span className="flex items-center gap-1 text-yellow-500 font-bold mr-1">
                              ★ {request.buyerRating}
                            </span>
                          </div>
                          {request.latestSeller && (
                            <div className="flex items-center gap-2 rounded-xl bg-white px-2 py-1">
                              <UserAvatar
                                user={request.latestSeller}
                                className="h-9 w-9"
                                rounded="rounded-full"
                              />
                              <span>
                                فروشنده پیشنهاددهنده:{" "}
                                <b className="text-gray-800">
                                  {request.latestSeller.fullName}
                                </b>
                              </span>
                            </div>
                          )}
                        </div>
                      </div>
                      <div className="flex flex-wrap items-center gap-3">
                        <span className="text-gray-500 text-sm font-bold bg-gray-50 px-3 py-1.5 rounded-lg">
                          {request.offers} پیشنهاد
                        </span>
                        {userRole === "seller" ? (
                          <Link
                            href={`/requests/${request.id}/offer`}
                            className="rounded-lg border border-[#00a8e8]/30 bg-blue-50 px-4 py-2.5 text-sm font-bold text-[#00a8e8] hover:bg-blue-100 transition"
                          >
                            مشخصات کالای پیشنهادی
                          </Link>
                        ) : request.offers > 0 ? (
                          <button
                            type="button"
                            onClick={() => setSpecsRequest(request)}
                            className="rounded-lg border border-[#00a8e8]/30 bg-blue-50 px-4 py-2.5 text-sm font-bold text-[#00a8e8] hover:bg-blue-100 transition"
                          >
                            مشخصات کامل محصول پیشنهادی
                          </button>
                        ) : null}
                        <Link
                          href={`/requests/${request.id}`}
                          className="bg-green-600 text-white px-6 py-2.5 rounded-lg font-bold hover:bg-green-700 transition"
                        >
                          مشاهده و ارسال پیشنهاد
                        </Link>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function OfferSpecsModal({
  request,
