        offerId: selectedOffer.id,
        useAlternateAddress,
        shippingAddress,
        buyerConfirmedProductSpecs: true,
      });
      alert(result.message);
      setSelectedOffer(null);
      setActiveTab("orders");
      await loadDashboard();
