"use client";

import Link from "next/link";
import { useEffect, useMemo, useState, type ReactNode } from "react";
import SellerStars from "@/components/SellerStars";
import TradeSurvey from "@/components/TradeSurvey";
import { ProductImageStrip, ProductThumb } from "@/components/ProductImages";
import { generateInvoiceHTML } from "@/utils/invoiceGenerator";

const money = (value: string | number) =>
  `${Number(String(value).replace(/\D/g, "") || 0).toLocaleString("fa-IR")} تومان`;
const maskCard = (value = "") =>
  value ? `${value.slice(0, 4)}-****-****-${value.slice(-4)}` : "ثبت نشده";
const maskSheba = (value = "") =>
  value
    ? `${value.slice(0, 4)} **** **** **** **** ${value.slice(-4)}`
    : "ثبت نشده";
const dateLabel = (value?: string) =>
  value
    ? new Date(value).toLocaleString("fa-IR", {
        dateStyle: "short",
        timeStyle: "short",
      })
    : "—";

const paymentMethodLabel = (method?: string) => {
  if (method === "wallet") return "کیف پول";
  if (method === "zarinpal") return "زرین‌پال";
  if (method === "gateway") return "درگاه آزمایشی";
  return "در انتظار پرداخت";
};

const categoryMap: Record<string, string> = {
  digital: "کالای دیجیتال",
  clothing: "مد و پوشاک",
  home: "خانه و آشپزخانه",
  beauty: "زیبایی و سلامت",
  books: "کتاب و لوازم تحریر",
  sports: "ورزش و سفر",
  toys: "اسباب‌بازی و کودک",
  auto: "خودرو و موتور",
  industrial: "صنعتی و اداری",
  other: "سایر",
};

const defaultOfferSpecs = {
  brand: "",
  exactModel: "",
  serialOrConfig: "",
  cpu: "",
  ram: "",
  storage: "",
  gpu: "ندارد / نامرتبط",
  display: "",
  manufactureYear: "",
  productCondition: "used_good",
  warrantyStatus: "test",
  warrantyMonths: "",
  partsHealth: "all_healthy",
  cpuHealth: "healthy",
  motherboardHealth: "healthy",
  displayHealth: "healthy",
  storageHealth: "healthy",
  ramHealth: "healthy",
  gpuHealth: "not_applicable",
  keyboardTouchpadHealth: "healthy",
  bodyHingeHealth: "healthy",
  batteryHealthPercent: "",
  appearanceGrade: "A",
  repairHistory: "none",
  usageLevel: "normal",
  accessoriesStatus: "complete",
  chargerStatus: "original",
  originalPackaging: "unknown",
  purchaseInvoiceAvailable: "unknown",
  testDeadlineDays: "7",
  returnPolicy:
    "در صورت مغایرت مشخصات یا خرابی اعلام‌نشده، مرجوعی پذیرفته می‌شود.",
  notes: "",
};

type OfferSpecs = typeof defaultOfferSpecs;

const healthOptions = [
  ["healthy", "سالم"],
  ["minor_issue", "ایراد جزئی"],
  ["needs_repair", "نیازمند تعمیر"],
  ["not_applicable", "نامرتبط"],
] as const;

type SellerData = {
  seller: {
    id: number;
    fullName: string;
    email: string;
    avatarName?: string;
    walletBalance: number;
    bio?: string;
    categories?: string[];
    bankAccountHolder?: string;
    bankName?: string;
    bankAccountNumber?: string;
    bankCardNumber?: string;
    bankShebaNumber?: string;
    bankDetailsVerified?: boolean;
  };
  matchingRequests: any[];
  orders: any[];
  offers: any[];
  transactions: any[];
  withdrawals: any[];
  notifications: any[];
  messages: any[];
  reviews: any[];
};

export default function SellerDashboardPage() {
  const [activeTab, setActiveTab] = useState("overview");
  const [data, setData] = useState<SellerData | null>(null);
  const [sellerScore, setSellerScore] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [queueIndex, setQueueIndex] = useState(0);
  const [timeLeft, setTimeLeft] = useState(60);
  const [offerAmount, setOfferAmount] = useState("");
  const [offerDeliveryDays, setOfferDeliveryDays] = useState("3");
  const [offerMessage, setOfferMessage] = useState("");
  const [offerSpecs, setOfferSpecs] = useState<OfferSpecs>({
    ...defaultOfferSpecs,
  });
  const [isSubmittingOffer, setIsSubmittingOffer] = useState(false);
  const [trackingByOrder, setTrackingByOrder] = useState<
    Record<string, string>
  >({});
  const [withdrawalAmount, setWithdrawalAmount] = useState("");
  const [messageText, setMessageText] = useState("");
  const [activeChatUserId, setActiveChatUserId] = useState<number | null>(null);
  const [settings, setSettings] = useState({
    storeName: "",
    bio: "",
    categories: [] as string[],
  });
  const [storeAvatarFile, setStoreAvatarFile] = useState<File | null>(null);
  const [storeAvatarPreview, setStoreAvatarPreview] = useState("");

  const sellerId =
    typeof window === "undefined"
      ? 0
      : Number(localStorage.getItem("userId") || 0);

  const loadDashboard = async () => {
    if (!sellerId) {
      setError(
        "برای مشاهده داده‌های واقعی فروشنده، ابتدا با حساب فروشنده ثبت‌نام یا وارد شوید.",
      );
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const [dashboardResponse, scoreResponse] = await Promise.all([
        fetch(`/api/dashboard/seller?sellerId=${sellerId}`, {
          cache: "no-store",
        }),
        fetch(`/api/seller-score?sellerId=${sellerId}`, { cache: "no-store" }),
      ]);
      const dashboard = await dashboardResponse.json();
      const score = await scoreResponse.json();
      if (!dashboard.success)
        throw new Error(dashboard.message || "خطا در دریافت داشبورد فروشنده");
      setData(dashboard);
      if (score.success) setSellerScore(score.score);
      setSettings({
        storeName: dashboard.seller.fullName || "",
        bio: dashboard.seller.bio || "",
        categories: dashboard.seller.categories || [],
      });
      setStoreAvatarPreview(
        dashboard.seller.avatarName
          ? `/api/avatar?userId=${dashboard.seller.id}&v=${encodeURIComponent(dashboard.seller.avatarName)}`
          : "",
      );
      setStoreAvatarFile(null);
      setActiveChatUserId(
        (current) =>
          current ||
          dashboard.orders[0]?.buyerId ||
          dashboard.matchingRequests[0]?.buyerId ||
          null,
      );
      setQueueIndex(0);
      setTimeLeft(60);
      setError("");
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "ارتباط با سرور ناموفق بود.",
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadDashboard();
  }, []);

  const action = async (url: string, body: Record<string, unknown>) => {
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    const result = await response.json();
    if (!result.success) throw new Error(result.message || "عملیات ناموفق بود");
    return result;
  };

  const updateOfferSpec = (key: keyof OfferSpecs, value: string) => {
    setOfferSpecs((current) => ({ ...current, [key]: value }));
  };

  const resetOfferForm = () => {
    setOfferAmount("");
    setOfferMessage("");
    setOfferSpecs({ ...defaultOfferSpecs });
  };

  const queue = data?.matchingRequests || [];
  const currentRequest = queue[queueIndex] || null;
  const remainingQueue = queue.slice(queueIndex);
  const pendingPayment = (data?.orders || []).filter(
    (order) => order.status === "pending_payment",
  );
  const readyToShip = (data?.orders || []).filter(
    (order) => order.status === "paid",
  );
  const shipped = (data?.orders || []).filter(
    (order) => order.status === "shipped",
  );
  const archiveOrders = (data?.orders || []).filter(
    (order) =>
      order.sellerArchived ||
      ["completed", "cancelled", "returned"].includes(order.status),
  );
  const reviewedOrderIds = new Set(
    (data?.reviews || [])
      .filter((review) => review.reviewerId === data?.seller.id)
      .map((review) => review.orderId),
  );
  const pendingSurveys = (data?.orders || []).filter(
    (order) => order.status === "completed" && !reviewedOrderIds.has(order.id),
  );
  const ordersById = new Map(
    (data?.orders || []).map((order) => [order.id, order]),
  );
  const receivedReviews = (data?.reviews || []).filter(
    (review) => review.revieweeId === data?.seller.id,
  );

  useEffect(() => {
    if (!currentRequest) return;
    if (timeLeft <= 0) {
      void rejectCurrent();
      return;
    }
    const timer = setTimeout(() => setTimeLeft((value) => value - 1), 1000);
    return () => clearTimeout(timer);
  }, [currentRequest, timeLeft]);

  const rejectCurrent = async () => {
    if (!currentRequest || !data) return;
    try {
      await action("/api/seller-request-action", {
        sellerId: data.seller.id,
        requestId: currentRequest.id,
        action: "rejected",
      });
    } catch {
      /* progress locally even if API transiently fails */
    }
    setQueueIndex((value) => value + 1);
    setTimeLeft(60);
    resetOfferForm();
  };

  const submitOffer = async () => {
    if (!data || !currentRequest) return;
    const amount = offerAmount.replace(/\D/g, "");
    if (!amount) {
      alert("قیمت پیشنهادی را وارد کنید.");
      return;
    }
    setIsSubmittingOffer(true);
    try {
      const result = await action("/api/submit-offer", {
        sellerId: data.seller.id,
        requestId: currentRequest.id,
        amount,
        deliveryDays: Number(offerDeliveryDays),
        message: offerMessage,
        productSpecs: offerSpecs,
      });
      alert(result.message);
      setQueueIndex((value) => value + 1);
      setTimeLeft(60);
      resetOfferForm();
      await loadDashboard();
    } catch (err) {
      alert(err instanceof Error ? err.message : "ثبت پیشنهاد ناموفق بود");
    } finally {
      setIsSubmittingOffer(false);
    }
  };

  const shipOrder = async (orderId: string) => {
    if (!data) return;
    const trackingCode = trackingByOrder[orderId] || "";
    if (!trackingCode.trim()) {
      alert("کد رهگیری ارسال را وارد کنید.");
      return;
    }
    try {
      const result = await action("/api/orders/ship", {
        sellerId: data.seller.id,
        orderId,
        trackingCode,
      });
      alert(result.message);
      await loadDashboard();
    } catch (err) {
      alert(err instanceof Error ? err.message : "تایید ارسال ناموفق بود");
    }
  };

  const requestWithdrawal = async () => {
    if (!data || !withdrawalAmount) return;
    try {
      const result = await action("/api/wallet/withdraw", {
        userId: data.seller.id,
        amount: withdrawalAmount,
      });
      setWithdrawalAmount("");
      alert(result.message);
      await loadDashboard();
    } catch (err) {
      alert(err instanceof Error ? err.message : "درخواست برداشت ناموفق بود.");
    }
  };

  const archiveOrder = async (orderId: string) => {
    if (!data) return;
    try {
      const result = await action("/api/orders/archive", {
        userId: data.seller.id,
        orderId,
        role: "seller",
      });
      alert(result.message);
      await loadDashboard();
    } catch (err) {
      alert(err instanceof Error ? err.message : "بایگانی ناموفق بود");
    }
  };

  const handleStoreAvatarChange = (file?: File | null) => {
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      alert("لطفاً یک فایل تصویری معتبر برای لوگوی فروشگاه انتخاب کنید.");
      return;
    }
    setStoreAvatarFile(file);
    setStoreAvatarPreview(URL.createObjectURL(file));
  };

  const saveSettings = async () => {
    if (!data) return;
    try {
      const form = new FormData();
      form.append("sellerId", String(data.seller.id));
      form.append("fullName", settings.storeName);
      form.append("bio", settings.bio);
      form.append("categories", JSON.stringify(settings.categories));
      if (storeAvatarFile) form.append("avatar", storeAvatarFile);

      const response = await fetch("/api/seller/profile", {
        method: "PATCH",
        body: form,
      });
      const result = await response.json();
      if (!result.success) throw new Error(result.message);
      localStorage.setItem("userDisplayName", settings.storeName);
      setStoreAvatarFile(null);
      alert(result.message);
      await loadDashboard();
    } catch (err) {
      alert(err instanceof Error ? err.message : "ذخیره تنظیمات ناموفق بود");
    }
  };

  const counterpartUsers = useMemo(() => {
    const map = new Map<number, { id: number; name: string }>();
    for (const order of data?.orders || [])
      map.set(order.buyerId, { id: order.buyerId, name: order.buyerName });
    for (const req of data?.matchingRequests || [])
      map.set(req.buyerId, { id: req.buyerId, name: req.buyerName });
    return [...map.values()];
  }, [data]);
  const currentMessages = (data?.messages || []).filter(
    (message) =>
      message.senderId === activeChatUserId ||
      message.receiverId === activeChatUserId,
  );

  const sendMessage = async () => {
    if (!data || !activeChatUserId || !messageText.trim()) return;
    try {
      const result = await action("/api/messages", {
        senderId: data.seller.id,
        receiverId: activeChatUserId,
        content: messageText,
      });
      setMessageText("");
      alert(result.message);
      await loadDashboard();
    } catch (err) {
      alert(err instanceof Error ? err.message : "ارسال پیام ناموفق بود");
    }
  };

  const tabs = [
    ["overview", "پیشخوان", "🏠"],
    ["requests", "رادار درخواست‌ها", "📡"],
    ["orders", "سفارش‌ها", "📦"],
    ["shipping", "ارسال کالا", "🚚"],
    ["wallet", "کیف پول", "💰"],
    ["messages", "پیام‌ها", "💬"],
    ["reviews", "دیدگاه‌ها", "🗣️"],
    ["notifications", "اعلان‌ها", "🔔"],
    ["survey", "نظرسنجی", "⭐"],
    ["archive", "بایگانی", "🗂️"],
    ["settings", "تنظیمات", "⚙️"],
  ] as const;

  if (loading)
    return (
      <div
        dir="rtl"
        className="grid min-h-[60vh] place-items-center bg-gray-50 text-[#003b5c]"
      >
        در حال بارگذاری داشبورد فروشنده...
      </div>
    );
  if (error || !data)
    return (
      <div
        dir="rtl"
        className="mx-auto mt-12 max-w-xl rounded-3xl border border-amber-200 bg-amber-50 p-8 text-center"
      >
        <h1 className="text-xl font-bold text-amber-900">
          داشبورد فروشنده آماده نیست
        </h1>
        <p className="mt-3 text-sm leading-7 text-amber-800">{error}</p>
        <Link
          href="/register"
          className="mt-6 inline-block rounded-xl bg-[#003b5c] px-6 py-3 font-bold text-white"
        >
          ثبت‌نام فروشنده
        </Link>
      </div>
    );

  return (
    <div dir="rtl" className="min-h-screen bg-[#f8fcfb] pb-16">
      {currentRequest && (
        <section className="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4 backdrop-blur-sm">
          <div className="relative max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-[2rem] border-4 border-[#0b9c56] bg-white p-6 shadow-2xl">
            <div className="absolute -right-10 -top-10 h-32 w-32 animate-ping rounded-full bg-green-500/20" />
            <div className="relative z-10 mb-4 flex justify-between">
              <span className="rounded-full bg-red-500 px-3 py-1 text-xs font-bold text-white animate-pulse">
                درخواست مرتبط {queueIndex + 1} از {queue.length}
              </span>
              <span
                className={`font-mono text-2xl font-bold ${timeLeft <= 10 ? "animate-bounce text-red-600" : "text-gray-800"}`}
              >
                00:{timeLeft < 10 ? `0${timeLeft}` : timeLeft}
              </span>
            </div>
            <div className="relative z-10 flex items-start gap-3">
              <ProductThumb
                images={currentRequest.productImages}
                title={currentRequest.title}
                className="h-20 w-20"
              />
              <div className="min-w-0">
                <h2 className="text-xl font-bold text-[#003b5c]">
                  {currentRequest.title}
                </h2>
                <p className="mt-2 text-sm leading-7 text-gray-600">
                  {currentRequest.description}
                </p>
              </div>
            </div>
            <ProductImageStrip
              images={currentRequest.productImages}
              title={currentRequest.title}
              label="عکس‌های محصول ثبت‌شده توسط خریدار"
            />
            <div className="relative z-10 mt-4 space-y-2 rounded-2xl bg-gray-50 p-4 text-sm">
              <p>
                دسته: <b className="text-blue-700">{currentRequest.category}</b>
              </p>
              <p>
                خریدار: <b>{currentRequest.buyerName}</b>
              </p>
              <p>
                تعداد: <b>{currentRequest.quantity}</b>
              </p>
              <p className="border-t pt-2">
                بودجه:{" "}
                <b className="text-lg text-green-600">
                  {money(currentRequest.budget)}
                </b>
              </p>
            </div>
            <div className="relative z-10 mt-4 rounded-2xl bg-blue-50 p-4">
              <p className="font-bold text-[#003b5c]">
                ثبت پیشنهاد و مشخصات کالا در صفحه جداگانه
              </p>
              <p className="mt-2 text-sm leading-7 text-blue-900">
                برای جلوگیری از بسته شدن فرم و ثبت دقیق مشخصات، قیمت و مشخصات
                کامل محصول پیشنهادی را در صفحه اختصاصی پر کنید.
              </p>
              <Link
                href={`/requests/${currentRequest.id}/offer`}
                className="mt-4 inline-block rounded-xl bg-[#003b5c] px-5 py-3 text-sm font-bold text-white hover:bg-[#002d46]"
              >
                رفتن به فرم مشخصات کالای پیشنهادی
              </Link>
            </div>
            <div className="relative z-10 mt-4 flex gap-3">
              <button
                onClick={rejectCurrent}
                className="flex-1 rounded-xl bg-gray-100 py-3 font-bold text-gray-700"
              >
                رد و مورد بعدی
              </button>
              <Link
                href={`/requests/${currentRequest.id}/offer`}
                className="flex-[2] rounded-xl bg-[#0b9c56] py-3 text-center font-bold text-white"
              >
                تکمیل فرم و ثبت پیشنهاد
              </Link>
            </div>
            <div
              className="absolute bottom-0 left-0 h-1.5 bg-[#0b9c56]"
              style={{ width: `${(timeLeft / 60) * 100}%` }}
            />
          </div>
        </section>
      )}

      <div className="border-b bg-white px-4 py-3 shadow-sm">
        <div className="mx-auto flex max-w-6xl justify-between text-sm text-gray-500">
          <span>OptiBid / داشبورد فروشنده</span>
          <span>{data.seller.fullName}</span>
        </div>
      </div>
      <div className="mx-auto max-w-6xl px-4 py-8">
        <section className="mb-6 grid grid-cols-2 gap-4 md:grid-cols-4">
          <Metric
            value={remainingQueue.length}
            label="درخواست مرتبط"
            color="blue"
          />
          <Metric
            value={pendingPayment.length}
            label="منتظر پرداخت خریدار"
            color="amber"
          />
          <Metric
            value={readyToShip.length}
            label="آماده ارسال"
            color="orange"
          />
          <Metric
            value={money(data.seller.walletBalance)}
            label="کیف پول فروشنده"
            color="green"
          />
        </section>
        <section className="mb-6 overflow-hidden rounded-2xl border border-blue-100 bg-white shadow-sm">
          <div className="flex flex-col justify-between gap-3 bg-gradient-to-l from-[#003b5c] to-[#005e94] p-5 text-white md:flex-row md:items-center">
            <div>
              <p className="text-sm font-bold text-blue-100">
                امتیاز اعتماد فروشنده
              </p>
              <h2 className="mt-1 text-2xl font-bold">
                {sellerScore?.label || "در حال ارزیابی"}
              </h2>
            </div>
            <div>
              <SellerStars
                score={sellerScore?.finalScore || 0}
                size="lg"
                light
              />
              <p className="mt-1 text-xs text-blue-100">
                اعتبار داده: {sellerScore?.confidence || 0}%
              </p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-px bg-gray-100 md:grid-cols-4">
            <Metric
              value={`${sellerScore?.rates.responseRate24h || 0}%`}
              label="پاسخ ۲۴ساعته"
              color="plain"
            />
            <Metric
              value={`${sellerScore?.rates.onTimeShippingRate || 0}%`}
              label="ارسال به‌موقع"
              color="plain"
            />
            <Metric
              value={`${sellerScore?.rates.validTrackingRate || 0}%`}
              label="رهگیری معتبر"
              color="plain"
            />
            <Metric
              value={`${sellerScore?.rates.defectRate || 0}%`}
              label="نرخ نقص"
              color="plain"
            />
          </div>
        </section>
        <div className="mb-8 flex flex-wrap justify-center gap-2 rounded-[2rem] border border-gray-200 bg-white/70 p-4 shadow-sm">
          {tabs.map(([id, label, icon]) => (
            <button
              key={id}
              onClick={() => setActiveTab(id)}
              className={`rounded-full border px-4 py-2 text-sm font-bold ${activeTab === id ? "border-[#003b5c] bg-[#003b5c] text-white" : "border-gray-200 bg-white text-gray-600 hover:bg-blue-50"}`}
            >
              {icon} {label}
              {id === "requests" && remainingQueue.length
                ? ` (${remainingQueue.length})`
                : ""}
              {id === "shipping" && readyToShip.length
                ? ` (${readyToShip.length})`
                : ""}
              {id === "survey" && pendingSurveys.length
                ? ` (${pendingSurveys.length})`
                : ""}
            </button>
          ))}
        </div>

        {activeTab === "overview" && (
          <section className="grid gap-6 md:grid-cols-2">
            <div className="rounded-3xl border border-gray-200 bg-white p-6 shadow-sm">
              <h2 className="mb-4 font-bold text-[#003b5c]">
                درخواست‌های مرتبط در صف
              </h2>
              {remainingQueue.length === 0 ? (
                <Empty text="درخواستی در حوزه‌های شما باقی نمانده است." />
              ) : (
                remainingQueue.map((req, index) => (
                  <div
                    key={req.id}
