import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import {
  authenticateOrCreateJsonSocialUser,
  getJsonPlatformFinance,
  type SocialAuthProvider,
} from "@/lib/json-store";

export const dynamic = "force-dynamic";

type Provider = SocialAuthProvider;
type RouteContext = {
  params: Promise<{ provider: string }> | { provider: string };
};

type SocialState = {
  provider: Provider;
  role: "buyer" | "seller";
  redirect: string;
  nonce: string;
};

function providerFromValue(value: string): Provider | null {
  return value === "google" || value === "facebook" ? value : null;
}

async function readProvider(context: RouteContext) {
  const params = await context.params;
  return providerFromValue(params.provider);
}

function baseUrlFromRequest(request: Request) {
  const configured = process.env.NEXT_PUBLIC_SITE_URL?.replace(/\/+$/, "");
  if (configured?.startsWith("https://")) return configured;
  const url = new URL(request.url);
  return `${url.protocol}//${url.host}`;
}

function decodeState(value: string): SocialState | null {
  try {
    const parsed = JSON.parse(Buffer.from(value, "base64url").toString("utf8"));
    if (
      parsed &&
      (parsed.provider === "google" || parsed.provider === "facebook") &&
      (parsed.role === "buyer" || parsed.role === "seller") &&
      typeof parsed.nonce === "string"
    ) {
      return {
        provider: parsed.provider,
        role: parsed.role,
        redirect:
          typeof parsed.redirect === "string" &&
          parsed.redirect.startsWith("/") &&
          !parsed.redirect.startsWith("//")
            ? parsed.redirect
            : "",
        nonce: parsed.nonce,
      };
    }
  } catch {
    // invalid state
  }
  return null;
}

async function oauthConfig(provider: Provider) {
  const finance = await getJsonPlatformFinance().catch(() => null);
  const settings = finance?.settings;
  if (provider === "google") {
    return {
      clientId:
        process.env.GOOGLE_CLIENT_ID ||
        process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID ||
        settings?.googleOAuthClientId ||
        "",
      clientSecret:
        process.env.GOOGLE_CLIENT_SECRET ||
        settings?.googleOAuthClientSecret ||
        "",
      baseUrl: settings?.socialAuthBaseUrl || "",
      tokenUrl: "https://oauth2.googleapis.com/token",
      userInfoUrl: "https://www.googleapis.com/oauth2/v3/userinfo",
    };
  }
  return {
    clientId:
      process.env.FACEBOOK_CLIENT_ID ||
      process.env.NEXT_PUBLIC_FACEBOOK_CLIENT_ID ||
      settings?.facebookOAuthClientId ||
      "",
    clientSecret:
      process.env.FACEBOOK_CLIENT_SECRET ||
      settings?.facebookOAuthClientSecret ||
      "",
    baseUrl: settings?.socialAuthBaseUrl || "",
    tokenUrl: "https://graph.facebook.com/v20.0/oauth/access_token",
    userInfoUrl:
      "https://graph.facebook.com/me?fields=id,name,email,picture.width(256).height(256)",
  };
}

function escapeHtml(value: unknown) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function resultHtml(input: {
  ok: boolean;
  title: string;
  message: string;
  user?: { id: number; fullName: string; role: string };
  redirect?: string;
}) {
  const userJson = input.user
    ? JSON.stringify(input.user).replace(/</g, "\\u003c")
    : "null";
  const redirectJson = JSON.stringify(input.redirect || "");
  return `<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><title>${escapeHtml(input.title)}</title><style>body{margin:0;background:linear-gradient(135deg,#16a34a,#003b5c);font-family:Tahoma,Arial,sans-serif;color:#0f172a}.wrap{min-height:100vh;display:grid;place-items:center;padding:24px}.card{max-width:520px;width:100%;background:#fff;border-radius:28px;padding:32px;text-align:center;box-shadow:0 24px 70px rgba(15,23,42,.25)}.icon{width:74px;height:74px;border-radius:999px;margin:0 auto 18px;display:grid;place-items:center;font-size:32px;background:${input.ok ? "#dcfce7;color:#15803d" : "#fee2e2;color:#b91c1c"}}h1{margin:0 0 12px;color:#003b5c;font-size:23px}p{line-height:2;color:#475569}.btn{display:inline-block;margin-top:18px;border-radius:14px;background:#003b5c;color:white;padding:12px 18px;text-decoration:none;font-weight:800}</style></head><body><main class="wrap"><section class="card"><div class="icon">${input.ok ? "✓" : "!"}</div><h1>${escapeHtml(input.title)}</h1><p>${escapeHtml(input.message)}</p><a class="btn" href="/login">بازگشت به ورود</a></section></main>${input.ok && input.user ? `<script>const user=${userJson};localStorage.setItem("userRole",user.role);localStorage.setItem("userId",String(user.id));localStorage.setItem("userDisplayName",user.fullName);const saved=sessionStorage.getItem("redirectAfterAuth");if(saved)sessionStorage.removeItem("redirectAfterAuth");const preferred=${redirectJson};const dashboard='/' + (user.role === 'admin' ? 'admin' : user.role) + '/dashboard';setTimeout(()=>{window.location.replace((saved&&saved.startsWith('/')&&!saved.startsWith('//'))?saved:(preferred||dashboard));},900);</script>` : ""}</body></html>`;
}

async function exchangeGoogleCode(
  code: string,
  redirectUri: string,
  config: Awaited<ReturnType<typeof oauthConfig>>,
) {
  const response = await fetch(config.tokenUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Accept: "application/json",
    },
    body: new URLSearchParams({
      code,
      client_id: config.clientId,
      client_secret: config.clientSecret,
      redirect_uri: redirectUri,
      grant_type: "authorization_code",
    }),
  });
  const token = await response.json().catch(() => ({}));
  if (!response.ok || !token.access_token)
    throw new Error(
      token.error_description || token.error || "Google token exchange failed",
    );
  const profileResponse = await fetch(config.userInfoUrl, {
    headers: { Authorization: `Bearer ${token.access_token}` },
  });
  const profile = await profileResponse.json().catch(() => ({}));
  if (!profileResponse.ok || !profile.sub)
    throw new Error("Google profile fetch failed");
  return {
    providerUserId: String(profile.sub),
    email: String(profile.email || ""),
    fullName: String(profile.name || profile.email || "کاربر گوگل"),
  };
}

async function exchangeFacebookCode(
  code: string,
  redirectUri: string,
  config: Awaited<ReturnType<typeof oauthConfig>>,
) {
  const tokenUrl = new URL(config.tokenUrl);
  tokenUrl.searchParams.set("client_id", config.clientId);
  tokenUrl.searchParams.set("client_secret", config.clientSecret);
  tokenUrl.searchParams.set("redirect_uri", redirectUri);
  tokenUrl.searchParams.set("code", code);
  const response = await fetch(tokenUrl, {
    headers: { Accept: "application/json" },
  });
  const token = await response.json().catch(() => ({}));
  if (!response.ok || !token.access_token)
    throw new Error(
      token.error?.message ||
        token.error_description ||
        "Facebook token exchange failed",
    );
  const profileUrl = new URL(config.userInfoUrl);
  profileUrl.searchParams.set("access_token", String(token.access_token));
  const profileResponse = await fetch(profileUrl, {
    headers: { Accept: "application/json" },
  });
  const profile = await profileResponse.json().catch(() => ({}));
  if (!profileResponse.ok || !profile.id)
    throw new Error(profile.error?.message || "Facebook profile fetch failed");
  return {
    providerUserId: String(profile.id),
    email: String(
      profile.email || `facebook-${profile.id}@social.optibid.local`,
    ),
    fullName: String(profile.name || "کاربر فیسبوک"),
  };
}

export async function GET(request: Request, context: RouteContext) {
  const provider = await readProvider(context);
  const url = new URL(request.url);
  const stateParam = url.searchParams.get("state") || "";
  const code = url.searchParams.get("code") || "";
  const oauthError = url.searchParams.get("error") || "";
  const cookieStore = await cookies();
  const cookieState = cookieStore.get("optibid_social_state")?.value || "";

  if (!provider) {
    return new NextResponse(
      resultHtml({
        ok: false,
        title: "ورود اجتماعی نامعتبر",
        message: "ارائه‌دهنده ورود پشتیبانی نمی‌شود.",
      }),
      { status: 400, headers: { "Content-Type": "text/html; charset=utf-8" } },
    );
  }

  try {
    if (oauthError)
      throw new Error(`درخواست ورود توسط ارائه‌دهنده رد شد: ${oauthError}`);
    if (!stateParam || !cookieState || stateParam !== cookieState)
      throw new Error(
        "اعتبار نشست ورود اجتماعی منقضی شده است؛ لطفاً دوباره تلاش کنید.",
      );
    const state = decodeState(stateParam);
    if (!state || state.provider !== provider)
      throw new Error("State ورود اجتماعی نامعتبر است.");
    if (!code) throw new Error("کد تایید ورود اجتماعی دریافت نشد.");

    const config = await oauthConfig(provider);
    if (!config.clientId || !config.clientSecret)
      throw new Error("تنظیمات Client ID / Client Secret کامل نیست.");
    const redirectUri = `${(config.baseUrl || baseUrlFromRequest(request)).replace(/\/+$/, "")}/api/auth/social/${provider}/callback`;
    const profile =
      provider === "google"
        ? await exchangeGoogleCode(code, redirectUri, config)
        : await exchangeFacebookCode(code, redirectUri, config);
    const user = await authenticateOrCreateJsonSocialUser({
      provider,
      providerUserId: profile.providerUserId,
      email: profile.email,
      fullName: profile.fullName,
      role: state.role,
    });

    const response = new NextResponse(
      resultHtml({
        ok: true,
        title:
          provider === "google"
            ? "ورود با گوگل موفق بود"
            : "ورود با فیسبوک موفق بود",
        message: "حساب شما تایید شد و تا چند لحظه دیگر وارد داشبورد می‌شوید.",
        user: { id: user.id, fullName: user.fullName, role: user.role },
        redirect: state.redirect,
      }),
      { headers: { "Content-Type": "text/html; charset=utf-8" } },
    );
    response.cookies.set("optibid_social_state", "", { path: "/", maxAge: 0 });
    return response;
  } catch (error) {
    const detail =
      error instanceof Error ? error.message : "خطای ناشناخته در ورود اجتماعی";
    const response = new NextResponse(
      resultHtml({
        ok: false,
        title:
          provider === "google"
            ? "ورود با گوگل ناموفق بود"
            : "ورود با فیسبوک ناموفق بود",
        message: detail,
      }),
      { status: 400, headers: { "Content-Type": "text/html; charset=utf-8" } },
    );
    response.cookies.set("optibid_social_state", "", { path: "/", maxAge: 0 });
    return response;
  }
}

files.scripts/cf-ensure-kv.mjs:
/**
 * اطمینان از وجود KV Namespace برای دیپلوی Cloudflare Workers.
 *
 * این اسکریپت قبل از `wrangler deploy` اجرا می‌شود و شناسه KV مربوط به
 * binding `OPTIBID_KV` را داخل `wrangler.jsonc` ثبت می‌کند.
 *
 * حالت‌های پشتیبانی‌شده:
 *   1. اگر CLOUDFLARE_API_TOKEN موجود باشد، مستقیماً از Cloudflare REST API
 *      استفاده می‌شود. اگر CLOUDFLARE_ACCOUNT_ID/ACCOUNT_ID تنظیم نشده باشد،
 *      اسکریپت تلاش می‌کند account id را از خود API تشخیص دهد.
 *   2. اگر توکن صریح در محیط وجود نداشته باشد، اسکریپت با Wrangler CLI تلاش
 *      می‌کند Namespace را پیدا/ایجاد کند. این حالت برای Cloudflare Workers
 *      Builds مفید است؛ چون آن محیط می‌تواند Wrangler را با توکن داخلی خودش
 *      اجرا کند و دیگر نیازی به تنظیم دستی متغیرهای build نیست.
 */
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const PLACEHOLDER = "__OPTIBID_KV_ID__";
const EXPECTED_TITLE = "OPTIBID_KV";
const API_BASE = "https://api.cloudflare.com/client/v4";
const configPath = new URL("../wrangler.jsonc", import.meta.url).pathname;

function stripAnsi(value) {
  return String(value || "").replace(/\u001b\[[0-?]*[ -/]*[@-~]/g, "");
}

function getExplicitAccountId() {
  return (
    process.env.CLOUDFLARE_ACCOUNT_ID ||
    process.env.ACCOUNT_ID ||
    process.env.CF_ACCOUNT_ID ||
    ""
  ).trim();
}

function getCurrentNamespaceId() {
  const content = readFileSync(configPath, "utf8");
  const match = content.match(
    /"binding"\s*:\s*"OPTIBID_KV"[\s\S]*?"id"\s*:\s*"([^"]*)"/
  );
  return match?.[1] || "";
}

function patchWranglerConfig(namespaceId) {
  let content = readFileSync(configPath, "utf8");
  const currentId = getCurrentNamespaceId();
  if (currentId === namespaceId) {
    console.log("✔ شناسه KV از قبل در wrangler.jsonc ثبت است.");
    return;
  }
  if (currentId && currentId !== PLACEHOLDER) {
    console.log(
      `ℹ شناسه فعلی (${currentId.slice(0, 8)}…) با namespace پیدا شده مطابقت ندارد و به‌روزرسانی می‌شود.`
    );
  }
  content = content.replace(
    /("binding"\s*:\s*"OPTIBID_KV"[\s\S]*?"id"\s*:\s*")[^"]*(")/,
    `$1${namespaceId}$2`
  );
  writeFileSync(configPath, content);
  console.log(`✔ شناسه KV (${namespaceId}) در wrangler.jsonc ثبت شد.`);
}

async function cfFetch(path, { token, method = "GET", body } = {}) {
  const res = await fetch(`${API_BASE}${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok || json.success === false) {
    const detail =
      json.errors?.map((e) => e.message).join("; ") ||
      res.statusText ||
      `HTTP ${res.status}`;
    throw new Error(`Cloudflare API: ${detail}`);
  }
  return json;
}

async function resolveAccountId(token) {
  const explicit = getExplicitAccountId();
  if (explicit) return explicit;

  console.log("ℹ CLOUDFLARE_ACCOUNT_ID تنظیم نشده؛ در حال تشخیص account id از Cloudflare API…");
  const json = await cfFetch("/accounts?per_page=2", { token });
  const accounts = Array.isArray(json.result) ? json.result : [];
  if (accounts.length === 1 && accounts[0]?.id) {
    console.log(`✔ account id از API تشخیص داده شد: ${accounts[0].id}`);
    return accounts[0].id;
  }
  if (accounts.length === 0) {
    throw new Error("هیچ Cloudflare account قابل دسترسی با این توکن پیدا نشد.");
  }
  throw new Error(
    "این توکن به بیش از یک Cloudflare account دسترسی دارد؛ CLOUDFLARE_ACCOUNT_ID را تنظیم کنید."
  );
}

async function listAllNamespaces({ token, accountId }) {
  const namespaces = [];
  let page = 1;
  const perPage = 100;
  while (true) {
    const json = await cfFetch(
      `/accounts/${accountId}/storage/kv/namespaces?page=${page}&per_page=${perPage}`,
      { token }
    );
    const batch = Array.isArray(json.result) ? json.result : [];
    namespaces.push(...batch);
    const info = json.result_info;
    if (!info || page >= (info.total_pages || 1) || batch.length < perPage) {
      break;
    }
    page += 1;
  }
  return namespaces;
}

function findNamespaceId(namespaces) {
  const match =
    namespaces.find((ns) => ns.title === EXPECTED_TITLE) ||
    namespaces.find((ns) => ns.title?.endsWith(`-${EXPECTED_TITLE}`));
  return match ? match.id : null;
}

async function createNamespace({ token, accountId }) {
  const json = await cfFetch(`/accounts/${accountId}/storage/kv/namespaces`, {
    token,
    method: "POST",
    body: { title: EXPECTED_TITLE },
  });
  const id = json.result?.id;
  if (!id) {
    throw new Error("شناسه KV Namespace در پاسخ API پیدا نشد.");
  }
  return id;
}

async function ensureWithCloudflareApi(token) {
  const accountId = await resolveAccountId(token);
  const namespaces = await listAllNamespaces({ token, accountId });
  let namespaceId = findNamespaceId(namespaces);
  if (namespaceId) {
    console.log(`✔ KV Namespace موجود است: ${namespaceId}`);
  } else {
    console.log(`… KV Namespace یافت نشد؛ در حال ساخت ${EXPECTED_TITLE} …`);
    namespaceId = await createNamespace({ token, accountId });
    console.log(`✔ KV Namespace ساخته شد: ${namespaceId}`);
  }
  patchWranglerConfig(namespaceId);
}

function runWrangler(args) {
  const command = process.platform === "win32" ? "npx.cmd" : "npx";
  const result = spawnSync(command, ["wrangler", ...args], {
    cwd: new URL("..", import.meta.url).pathname,
    encoding: "utf8",
    env: { ...process.env, CI: "true" },
    stdio: ["ignore", "pipe", "pipe"],
  });
  const output = `${result.stdout || ""}\n${result.stderr || ""}`;
  if (result.status !== 0) {
    throw new Error(`Wrangler (${args.join(" ")}) ناموفق بود:\n${stripAnsi(output).trim()}`);
  }
  return output;
}

function parseJsonArrayFromWranglerOutput(output) {
  const cleaned = stripAnsi(output).trim();
  const start = cleaned.indexOf("[");
  const end = cleaned.lastIndexOf("]");
  if (start === -1 || end === -1 || end <= start) {
    return [];
  }
  try {
    const parsed = JSON.parse(cleaned.slice(start, end + 1));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function parseNamespaceIdFromCreateOutput(output) {
  const cleaned = stripAnsi(output);
  const patterns = [
    /"id"\s*:\s*"([a-f0-9]{32})"/i,
    /id\s*=\s*"([a-f0-9]{32})"/i,
    /\bid\b[^a-f0-9]*([a-f0-9]{32})/i,
  ];
  for (const pattern of patterns) {
    const match = cleaned.match(pattern);
    if (match?.[1]) return match[1];
  }
  return null;
}

async function ensureWithWranglerCli() {
  const existingId = getCurrentNamespaceId();
  if (existingId && existingId !== PLACEHOLDER) {
    console.log("✔ شناسه KV از قبل در wrangler.jsonc ثبت است؛ نیازی به ساخت/جستجو نیست.");
    return;
  }

  console.log("ℹ توکن صریح Cloudflare در محیط نیست؛ تلاش با احراز هویت داخلی Wrangler/Workers Builds…");
  const listOutput = runWrangler(["kv", "namespace", "list"]);
  const namespaces = parseJsonArrayFromWranglerOutput(listOutput);
  let namespaceId = findNamespaceId(namespaces);

  if (namespaceId) {
    console.log(`✔ KV Namespace موجود است: ${namespaceId}`);
  } else {
    console.log(`… KV Namespace یافت نشد؛ در حال ساخت ${EXPECTED_TITLE} با Wrangler …`);
    const createOutput = runWrangler([
      "kv",
      "namespace",
      "create",
      EXPECTED_TITLE,
      "--binding",
      EXPECTED_TITLE,
    ]);
    namespaceId = parseNamespaceIdFromCreateOutput(createOutput);
    if (!namespaceId) {
      throw new Error(
        `شناسه KV Namespace از خروجی Wrangler قابل تشخیص نبود:\n${stripAnsi(createOutput).trim()}`
      );
    }
    console.log(`✔ KV Namespace ساخته شد: ${namespaceId}`);
  }

  patchWranglerConfig(namespaceId);
}

async function main() {
  const configuredId = getCurrentNamespaceId();
  if (configuredId && configuredId !== PLACEHOLDER && process.env.CF_ENSURE_KV_FORCE !== "1") {
    console.log("✔ شناسه KV از قبل در wrangler.jsonc ثبت است.");
    return;
  }

  const token = process.env.CLOUDFLARE_API_TOKEN;
  if (token) {
    try {
      await ensureWithCloudflareApi(token);
      return;
    } catch (error) {
      // اگر account id به‌صورت صریح تنظیم نشده باشد، ممکن است Wrangler بتواند در
      // محیط Workers Builds با همان توکن داخلی account درست را تشخیص دهد.
      if (!getExplicitAccountId()) {
        console.warn(
          `⚠ مسیر API ناموفق بود؛ تلاش جایگزین با Wrangler CLI: ${
            error instanceof Error ? error.message : error
          }`
        );
        await ensureWithWranglerCli();
        return;
      }
      throw error;
    }
  }

  await ensureWithWranglerCli();
}

main().catch((error) => {
  console.error("cf-ensure-kv ناموفق بود:", error instanceof Error ? error.message : error);
  process.exit(1);
});

